package com.jiugeng.erp.product;
import static com.jiugeng.erp.product.ProductTypes.*;import com.jiugeng.erp.iam.AuthenticatedActor;import com.jiugeng.erp.iam.AuditHistoryLookup;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.util.List;import org.springframework.context.annotation.Profile;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @Profile("!mock") @RequestMapping("/api/v1/products") class ProductController{private final ProductService service;private final ProductSkuExportService exports;private final AuditHistoryLookup history;ProductController(ProductService service,ProductSkuExportService exports,AuditHistoryLookup history){this.service=service;this.exports=exports;this.history=history;}
@GetMapping @PreAuthorize("hasAuthority('products.read')") List<ProductView> products(Authentication a){return service.products(has(a,"suppliers.read"));}
@GetMapping("/skus") @PreAuthorize("hasAuthority('products.read')") SkuPage skus(@RequestParam(defaultValue="")String field,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="true")boolean exact,@RequestParam(required=false)VariantStatus status,@RequestParam(required=false)ProductStatus productStatus,@RequestParam(required=false)Boolean hasImage,@RequestParam(required=false)Boolean hasSupplier,@RequestParam(required=false)Boolean hasMaterial,@RequestParam(defaultValue="updatedAt")String sort,@RequestParam(defaultValue="desc")String direction,@RequestParam(defaultValue="0")@Min(0)int page,@RequestParam(defaultValue="20")@Min(1)@Max(100)int size,Authentication a){return service.skus(field,q,exact,status,productStatus,hasImage,hasSupplier,hasMaterial,sort,direction,page,size,has(a,"suppliers.read"));}
@GetMapping("/skus/export") @PreAuthorize("hasAuthority('products.read')") org.springframework.http.ResponseEntity<byte[]> exportSkus(@RequestParam(defaultValue="")String field,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="true")boolean exact,@RequestParam(required=false)VariantStatus status,@RequestParam(required=false)ProductStatus productStatus,@RequestParam(required=false)Boolean hasImage,@RequestParam(required=false)Boolean hasSupplier,@RequestParam(required=false)Boolean hasMaterial,@RequestParam(required=false)List<String>variantIds,Authentication a){SkuPage result=service.skus(field,q,exact,status,productStatus,hasImage,hasSupplier,hasMaterial,"updatedAt","desc",0,10001,has(a,"suppliers.read"));List<SkuListItem> rows=variantIds==null||variantIds.isEmpty()?result.items():result.items().stream().filter(item->variantIds.contains(item.variant().id())).toList();if(rows.size()>10000)throw new ProductException(400,"SKU_EXPORT_LIMIT_EXCEEDED","导出最多 10000 条，请缩小筛选范围");byte[] content=exports.export(rows);return org.springframework.http.ResponseEntity.ok().contentType(org.springframework.http.MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")).header(org.springframework.http.HttpHeaders.CONTENT_DISPOSITION,org.springframework.http.ContentDisposition.attachment().filename("product-skus.xlsx").build().toString()).body(content);}
@GetMapping("/{id}") @PreAuthorize("hasAuthority('products.read')") ProductView product(@PathVariable String id,Authentication a){return service.product(id,has(a,"suppliers.read"));}
@GetMapping("/{id}/history") @PreAuthorize("hasAuthority('products.read')") List<AuditHistoryLookup.HistoryEvent> history(@PathVariable String id){service.product(id,false);return history.find("PRODUCT",id);}
@PostMapping @PreAuthorize("hasAuthority('products.write')") ProductView create(@Valid@RequestBody ProductRequest r,@AuthenticationPrincipal AuthenticatedActor actor,Authentication a){return service.create(r.input(),actor,has(a,"suppliers.read"));}
@PutMapping("/{id}") @PreAuthorize("hasAuthority('products.write')") ProductView update(@PathVariable String id,@Valid@RequestBody ProductRequest r,@AuthenticationPrincipal AuthenticatedActor actor,Authentication a){return service.update(id,r.input(),actor,has(a,"suppliers.read"));}
@PostMapping("/{id}/disable") @PreAuthorize("hasAuthority('products.write')") ProductView disable(@PathVariable String id,@Valid@RequestBody VersionRequest r,@AuthenticationPrincipal AuthenticatedActor actor,Authentication a){return service.disable(id,r.version(),actor,has(a,"suppliers.read"));}
@PostMapping("/skus/batch") @PreAuthorize("hasAuthority('products.write')") List<ProductView> batch(@Valid@RequestBody BatchRequest r,@AuthenticationPrincipal AuthenticatedActor actor,Authentication a){return service.batch(r.items().stream().map(BatchItem::input).toList(),actor,has(a,"suppliers.read"));}
private boolean has(Authentication a,String authority){return a.getAuthorities().stream().anyMatch(v->v.getAuthority().equals(authority));}
record ProductRequest(@NotBlank@Size(max=64)String productCode,@Size(max=200)String productName,@Size(max=200)String nameZh,@Size(max=100)String productType,@Size(max=1000)String description,ProductStatus status,Long version,@NotEmpty@Size(max=100)List<@Valid VariantRequest>variants){ProductInput input(){String name=productName==null||productName.isBlank()?nameZh:productName;return new ProductInput(productCode,name,productType,description,status,version,variants.stream().map(VariantRequest::input).toList());}}
record VariantRequest(String id,@NotBlank@Size(max=64)String skuCode,@NotBlank@Size(max=200)String variantName,@Size(max=200)String itemDimensions,@Size(max=200)String packageDimensions,@DecimalMin(value="0",inclusive=false)@Digits(integer=6,fraction=3)BigDecimal itemLengthCm,@DecimalMin(value="0",inclusive=false)@Digits(integer=6,fraction=3)BigDecimal itemWidthCm,@DecimalMin(value="0",inclusive=false)@Digits(integer=6,fraction=3)BigDecimal itemHeightCm,@DecimalMin(value="0",inclusive=false)@Digits(integer=6,fraction=3)BigDecimal packageLengthCm,@DecimalMin(value="0",inclusive=false)@Digits(integer=6,fraction=3)BigDecimal packageWidthCm,@DecimalMin(value="0",inclusive=false)@Digits(integer=6,fraction=3)BigDecimal packageHeightCm,@DecimalMin(value="0",inclusive=false)@Digits(integer=9,fraction=3)BigDecimal packageWeightGrams,VariantStatus status,@Size(max=36)String imageAssetId,@Size(max=500)String imageUrl,Long version,@Size(max=50)List<@Valid SupplierRequest>suppliers,@Size(max=100)List<@Valid MaterialRequest>materials){VariantInput input(){return new VariantInput(id,skuCode,variantName,itemDimensions,packageDimensions,itemLengthCm,itemWidthCm,itemHeightCm,packageLengthCm,packageWidthCm,packageHeightCm,packageWeightGrams,status,imageAssetId,imageUrl,version,suppliers==null?List.of():suppliers.stream().map(SupplierRequest::input).toList(),materials==null?List.of():materials.stream().map(MaterialRequest::input).toList());}}
record SupplierRequest(@NotBlank@Size(max=36)String supplierId,@Size(max=500)String purchaseUrl,@Size(max=500)String remark,boolean primary){SupplierAssignment input(){return new SupplierAssignment(supplierId,purchaseUrl,remark,primary);}}
record MaterialRequest(@NotBlank@Size(max=36)String materialId,@NotNull@DecimalMin(value="0",inclusive=false)BigDecimal standardQuantity,@NotBlank@Size(max=32)String unit,@DecimalMin("0")@DecimalMax("1")BigDecimal lossRate,@Size(max=1000)String remark,Boolean enabled){MaterialAssignment input(){return new MaterialAssignment(materialId,standardQuantity,unit,lossRate,remark,enabled==null||enabled);}}
record VersionRequest(@Min(0)long version){}
record BatchRequest(@NotEmpty@Size(max=100)List<@Valid BatchItem>items){}
record BatchItem(@NotBlank String productId,@NotBlank String variantId,@Min(0)long productVersion,@Min(0)long variantVersion,VariantStatus status,boolean statusSelected,BigDecimal itemLengthCm,BigDecimal itemWidthCm,BigDecimal itemHeightCm,boolean itemDimensionsSelected,BigDecimal packageLengthCm,BigDecimal packageWidthCm,BigDecimal packageHeightCm,boolean packageDimensionsSelected,BigDecimal packageWeightGrams,boolean packageWeightSelected){BatchVariantPatch input(){return new BatchVariantPatch(productId,variantId,productVersion,variantVersion,status,statusSelected,itemLengthCm,itemWidthCm,itemHeightCm,itemDimensionsSelected,packageLengthCm,packageWidthCm,packageHeightCm,packageDimensionsSelected,packageWeightGrams,packageWeightSelected);}}
}
